<?php
defined('ABSPATH') || exit;

/** Bounded, previewed taxonomy import and explicitly reviewed research enrichment. */
final class CAFCC_Corpus_Import {
    public static function taxonomy_execute($input){
        $editions=$input['editions']??array();$nodes=$input['nodes']??array();if(!is_array($editions)||!array_is_list($editions)||count($editions)>10||!is_array($nodes)||!array_is_list($nodes)||count($nodes)>100||!$nodes)return CAFCC_Repository::error('Use 1–100 hierarchy rows per checkpointed batch.');
        global $wpdb;$st=CAFCC_DB::table('subjects');$added=0;$retained=0;$warnings=array();
        foreach($editions as $e){if(!is_array($e)||array_diff(array_keys($e),array('edition_key','subject_code','title','applicability','source_url','review_status','publication_status')))return CAFCC_Repository::error('Invalid edition fields.');$subject=$wpdb->get_var($wpdb->prepare("SELECT id FROM $st WHERE code=%s",$e['subject_code']??''));if(!$subject)return CAFCC_Repository::error('Unknown edition subject.');$old=CAFCC_Academic::by_key('editions',$e['edition_key']??'');if($old){if((int)$old['subject_id']!==(int)$subject)return CAFCC_Repository::error('Existing edition identity conflicts.',409);continue;}$data=array_intersect_key($e,array_flip(array('edition_key','title','applicability','source_url')));$data=array_merge($data,array('subject_id'=>(int)$subject,'review_status'=>'needs_review','publication_status'=>'draft'));$saved=CAFCC_Academic::save('editions',$data,0,null,true);if(is_wp_error($saved))return $saved;}
        foreach($nodes as $n){if(!is_array($n)||array_diff(array_keys($n),array('node_key','edition_key','subject_code','parent_key','node_type','title','heading_number','printed_page','position','heading_origin','source_url','source_location','review_status','publication_status')))return CAFCC_Repository::error('Invalid official hierarchy fields.');if(($n['heading_origin']??'')!=='official'&&($n['heading_origin']??'')!=='editorial')return CAFCC_Repository::error('Identify official versus editorial origin.');$ed=CAFCC_Academic::by_key('editions',$n['edition_key']??'');if(!$ed)return CAFCC_Repository::error('Import the parent edition first.');$parent=!empty($n['parent_key'])?CAFCC_Academic::by_key('taxonomy',$n['parent_key']):null;if(!empty($n['parent_key'])&&!$parent)return CAFCC_Repository::error('Import parent '.$n['parent_key'].' first.');$old=CAFCC_Academic::by_key('taxonomy',$n['node_key']??'');
            if($old){if((int)$old['edition_id']!==(int)$ed['id']||$old['node_type']!==$n['node_type']||(int)$old['parent_id']!==(int)($parent['id']??0))return CAFCC_Repository::error('Existing hierarchy identity conflicts; no remapping allowed.',409);if($old['title']!==$n['title'])$warnings[]=array('key'=>$n['node_key'],'message'=>'Existing wording retained. Compare the exact contents-page wording in the private hierarchy package. No approved heading was overwritten.');$retained++;continue;}
            $data=array_intersect_key($n,array_flip(array('node_key','node_type','title','position','heading_origin','source_url','source_location')));$data=array_merge($data,array('edition_id'=>(int)$ed['id'],'subject_id'=>(int)$ed['subject_id'],'parent_id'=>$parent?(int)$parent['id']:null,'review_status'=>'needs_review','publication_status'=>'draft'));$saved=CAFCC_Academic::save('taxonomy',$data,0,null,true);if(is_wp_error($saved))return $saved;$added++;
        }
        return array('added_drafts'=>$added,'retained_existing'=>$retained,'warnings'=>$warnings,'published'=>0);
    }
    public static function preview($input){
        if(is_wp_error($e=CAFCC_Studio::admin()))return $e;if(!is_array($input)||array_diff(array_keys($input),array('batch_key','editions','nodes'))||!is_string($input['batch_key']??null)||!preg_match('/^[A-Za-z0-9_.:-]{2,120}$/D',$input['batch_key']))return CAFCC_Repository::error('Use a stable named hierarchy batch.');
        $result=null;$probe=CAFCC_Academic::transaction(function()use($input,&$result){$result=self::taxonomy_execute($input);return is_wp_error($result)?$result:new WP_Error('cafcc_taxonomy_preview_rollback','Preview only');});if($probe->get_error_code()!=='cafcc_taxonomy_preview_rollback')return $probe;
        $token=wp_generate_uuid4();set_transient('cafcc_v5_taxonomy_'.$token,array('owner'=>get_current_user_id(),'input'=>$input,'expires'=>time()+1800),1800);return array_merge($result,array('token'=>$token,'can_apply'=>true));
    }
    public static function apply($token){if(is_wp_error($e=CAFCC_Studio::admin()))return $e;if(!is_string($token)||!preg_match('/^[a-f0-9-]{36}$/D',$token))return CAFCC_Repository::error('Invalid preview.');$p=get_transient('cafcc_v5_taxonomy_'.$token);if(!$p||$p['owner']!==get_current_user_id()||$p['expires']<time())return CAFCC_Repository::error('Preview expired or belongs to another administrator.',409);return CAFCC_Academic::transaction(function()use($p,$token){$r=self::taxonomy_execute($p['input']);if(is_wp_error($r))return $r;delete_transient('cafcc_v5_taxonomy_'.$token);return $r;});}
    public static function enrich($id,$input){
        if(is_wp_error($e=CAFCC_Studio::admin()))return $e;if(!is_array($input)||array_diff(array_keys($input),array('expected_revision','record','confirmed'))||true!==($input['confirmed']??false))return CAFCC_Repository::error('Explicitly confirm enrichment of this current saved record.');
        return CAFCC_Academic::transaction(function()use($id,$input){$row=CAFCC_Studio::get($id,true);if(!$row)return CAFCC_Repository::error('Review not found.',404);if((string)$row['revision']!==(string)($input['expected_revision']??''))return CAFCC_Repository::error('Stale enrichment; existing corrections are retained.',409);$candidate=CAFCC_Studio::clean($input['record']??array());if(is_wp_error($candidate))return $candidate;
            foreach(array('stable_id','source_hash','source_key','subject_code','source_type','exam_attempt','mtp_series','section','reference','subreference') as $k)if((string)$candidate[$k] !== (string)$row['data'][$k])return CAFCC_Repository::error('Enrichment source identity differs; no existing ID was changed.',409);
            $data=$row['data'];if($data['rights_mode']==='reference_only'&&!empty($candidate['rich_content'])){$data['rights_mode']=$candidate['rights_mode'];$data['rights_basis']=$candidate['rights_basis'];}foreach(array('rich_content','review_question_text','review_answer_text') as $key){if(empty($data[$key]))$data[$key]=$candidate[$key];elseif($data[$key]!==$candidate[$key])return CAFCC_Repository::error('Existing content differs; inspect and correct it in Studio instead of overwriting it.',409);}
            foreach(array('source_hash','question_identity','question_reference','question_subreference') as $field)if(isset($data['answer'][$field],$candidate['answer'][$field])&&$data['answer'][$field]!==$candidate['answer'][$field])return CAFCC_Repository::error('Answer identity conflicts. Existing answer correction retained.',409);foreach($candidate['answer'] as $field=>$value)if(!array_key_exists($field,$data['answer']))$data['answer'][$field]=$value;$data['blocking_exceptions']=array_values(array_unique(array_merge($data['blocking_exceptions']??array(),$candidate['blocking_exceptions']??array())));
            // Never replace owner tags, decisions, notes, ledger or AI evidence.
            $result=CAFCC_Studio::save($id,array('expected_revision'=>$row['revision'],'data'=>$data));if(is_wp_error($result))return $result;if(!CAFCC_Studio::audit($result,'owner_enrichment_v5'))return CAFCC_Repository::error('Cannot retain enrichment history.',500);return $result;
        });
    }
    public static function init(){add_action('rest_api_init',function(){$p=function($r){return CAFCC_REST::permission($r,true);};foreach(array('preview','apply') as $action)register_rest_route('cafcc/v5','/admin/hierarchy/'.$action,array('methods'=>'POST','permission_callback'=>$p,'callback'=>function($r)use($action){$v=CAFCC_Studio::body($r);return is_wp_error($v)?$v:($action==='preview'?self::preview($v):self::apply($v['token']??null));}));register_rest_route('cafcc/v5','/admin/reviews/(?P<id>[1-9][0-9]{0,17})/enrich',array('methods'=>'POST','permission_callback'=>$p,'callback'=>function($r){$v=CAFCC_Studio::body($r);return is_wp_error($v)?$v:self::enrich((int)$r['id'],$v);}));});}
}
